// Renders the human-readable copy of the supplied program from its JSON
// source of truth (src/content/program.json + exercise-catalogue.json).
// docs/PROGRAM.md is generated by `npm run program:doc` and checked by a test.

export function renderProgramMarkdown(program, catalogue) {
  const byId = Object.fromEntries(catalogue.exercises.map((e) => [e.id, e]));
  const names = program.exerciseOrder.map((id) => byId[id].name.en);
  const lines = [];
  lines.push('<!-- GENERATED FILE — do not edit. Run `npm run program:doc` after changing src/content/program.json. -->');
  lines.push('');
  lines.push(`# Program ${program.programId} (version ${program.version})`);
  lines.push('');
  lines.push(`Supplied initial status: \`${program.initialStatus}\`. In this version of the app the owner chose to make the routine available straight away: there is no screening, approval or check-in step.`);
  lines.push('');
  lines.push('> These starter counts, progression checkpoints and UX choices are **conservative product proposals, not a medically validated prescription** for any individual. Changes require an explicit content revision by the owner with appropriate professional guidance.');
  lines.push('');
  lines.push('## Schedule, warm-up, pace and rest');
  lines.push('');
  lines.push(`- Default strengthening days: ${program.defaultWeekdays.join(' and ')}. The person may change days, keeping at least one full non-strength day between them (the app allows exactly two days a week).`);
  lines.push(`- Warm-up: ${program.warmupWalkSeconds / 60} minutes of comfortable easy walking around the house, only if appropriate and not symptom-provoking.`);
  lines.push(`- Exercise order: ${names.join(', ')}.`);
  lines.push('- Pace: about two seconds up/out and two seconds down/back, natural breathing. The app never forces a rhythm or counts reps from elapsed time.');
  lines.push(`- Rest: ${program.restSeconds} seconds between sets and exercises, with unlimited extension; 30–60 seconds to change sides in leg lifts.`);
  lines.push('- First session about 8–12 minutes including learning/rest; later about 15–20 minutes. No deadline.');
  lines.push('- Effort: several repetitions should still feel possible at the end. No straining, failure work, maximal or timed tests.');
  lines.push(`- Added load: ${program.automaticAddedLoadKg} kg at every stage. No loaded exercises.`);
  lines.push('');
  lines.push('## The eight stages (sets × repetitions)');
  lines.push('');
  lines.push(`| Stage | ${names.join(' | ')} |`);
  lines.push(`|---|${names.map(() => '---').join('|')}|`);
  for (const dose of program.stageDoses) {
    const cells = program.exerciseOrder.map((id, i) => {
      const perSide = id === 'supported-side-leg-lift' && program.sideLegLiftRepsArePerSide;
      const text = `${dose.sets[i]} × ${dose.reps[i]}${perSide ? ' each side' : ''}`;
      return dose.stage === 8 ? `Hold ${text}` : text;
    });
    lines.push(`| ${dose.stage} | ${cells.join(' | ')} |`);
  }
  lines.push('');
  lines.push(`After ${program.minimumFullSessionsPerStage} completed full practices at a stage, the app offers the next stage; the person chooses (default: "Keep this amount / 保持这个量"), and can also pick any stage on the Plan page. Stages are not calendar weeks. Stage 8 is maintenance — there is no stage 9 and no weight increase.`);
  lines.push('');
  lines.push('## Tiny session');
  lines.push('');
  for (const t of program.tinySession) lines.push(`- ${byId[t.exerciseId].name.en}: ${t.sets} × ${t.reps}`);
  lines.push(`- At least ${program.restSeconds} seconds rest between the two movements. Counts for progression: ${program.tinySessionCountsForProgression ? 'yes' : 'no'}.`);
  lines.push('');
  lines.push('## Exact exercise instructions (as supplied)');
  lines.push('');
  for (const id of program.exerciseOrder) {
    const ex = byId[id];
    lines.push(`### ${ex.name.en} / ${ex.name.zh}`);
    lines.push('');
    lines.push(`- Technique: ${ex.supplied.technique}`);
    lines.push(`- Benefit: ${ex.supplied.benefit}`);
    lines.push(`- If it is not suitable: ${ex.supplied.ifNotSuitable}`);
    lines.push('');
  }
  lines.push('## Coverage limitation');
  lines.push('');
  lines.push('This four-movement on-ramp omits substantial pulling and posterior-chain training, so it is **not** a complete all-major-muscle-groups program. A later review (at Stage 8, or earlier) should select suitable additional patterns and resistance with appropriate professional help. The app never fills the gap automatically (no rows, carries, curls or weights).');
  lines.push('');
  return lines.join('\n');
}
